// 仅模拟导航、主题、语言和更新状态；真实采样与安装由桌面程序执行。
const $=id=>document.getElementById(id), media=matchMedia('(prefers-color-scheme:dark)');
const names=['DotNet','Aurora','Ember','Default','Aquatic','Desert','Dusk','NightSky'];
let culture='zh-CN',mode='system',palette='DotNet',route='process',tab='appearance',state='idle',timer;
const t=key=>(window.translations[culture]||window.translations['en-US'])[key]||key;
function theme(){const dark=mode==='dark'||mode==='system'&&media.matches;for(const[k,v]of Object.entries(window.palettes[palette][dark?'dark':'light']))document.documentElement.style.setProperty('--'+k,v);Object.assign(document.documentElement.dataset,{theme:dark?'dark':'light',mode,palette});document.documentElement.style.colorScheme=dark?'dark':'light'}
function text(){document.documentElement.lang=culture;document.querySelectorAll('[data-key]').forEach(el=>el.textContent=t(el.dataset.key));document.querySelectorAll('[data-placeholder]').forEach(el=>el.placeholder=t(el.dataset.placeholder));$('status').textContent=t('AppSubtitle')}
const graph='<svg class="chart" viewBox="0 0 400 160" preserveAspectRatio="none"><line x1="0" y1="40" x2="400" y2="40"/><line x1="0" y1="80" x2="400" y2="80"/><line x1="0" y1="120" x2="400" y2="120"/><path d="M0 140 L45 110 80 125 120 60 160 100 200 50 250 80 300 60 350 85 400 40"/></svg>';
function settings(){const head='<div class="settings"><div class="settings-nav">'+[['appearance','SettingsAppearance'],['changelog','SettingsChangelog'],['about','SettingsAbout']].map(([id,key])=>`<button data-tab="${id}" class="${tab===id?'selected':''}">${t(key)}</button>`).join('')+'</div><div class="settings-page">';let body='';if(tab==='appearance')body=`<div class="form"><label for="mode">${t('ThemeMenu')}</label><select id="mode">${[['system','ThemeSystem'],['light','LightTheme'],['dark','DarkTheme']].map(([id,key])=>`<option value="${id}">${t(key)}</option>`).join('')}</select><label for="palette">${t('PaletteLabel')}</label><select id="palette">${names.map(name=>`<option value="${name}">${t((['DotNet','Aurora','Ember','Default'].includes(name)?'Palette':'Theme')+name)}</option>`).join('')}</select><label for="language">${t('LanguageMenu')}</label><select id="language"><option value="zh-CN">简体中文</option><option value="en-US">English</option><option value="zh-Hant">繁體中文</option><option value="ja-JP">日本語</option></select><label for="remember">${t('RememberWindowSize')}</label><input id="remember" type="checkbox"></div>`;else if(tab==='about')body=`<div class="about"><h2>NexusDash</h2><p>${t('AboutDescription')}</p><dl>${[['AboutVersion','0.1.10'],['AboutCompileTime','2026-10-15 12:00:00'],['AboutAuthor',t('AboutAuthorName')],['AboutRepository','https://github.com/dotnet9/NexusDash'],['AboutLicense','MIT'],['AboutCopyright','Copyright © 2026 CodeWF'],['AboutPlatform','.NET 10 · Avalonia 12 · Windows x64']].map(([key,v])=>`<dt>${t(key)}</dt><dd>${v}</dd>`).join('')}</dl><div class="update"><b>${t('UpdateCheck')}</b><p>${t('AboutUpdateDescription')}</p><p id="update-status"></p><progress id="progress" value="40" max="100" hidden></progress><button id="action"></button><button id="cancel" hidden>${t('AboutCancel')}</button></div></div>`;else body=`<h2>${t('SettingsChangelog')}</h2><p>0.1.10 · ${t('PaletteLabel')} / ${t('LanguageMenu')} / ${t('UpdateCheck')}</p>`;return head+body+'</div></div>'}
function render(){document.querySelectorAll('[data-route]').forEach(el=>el.classList.toggle('selected',el.dataset.route===route));if(route==='process')$('page').innerHTML='<div class="tabs"><button class="selected">'+t('ProcessOverview')+'</button><button>'+t('ProcessTree')+'</button><button>Treemap</button></div><div class="cards">'+[['CPU','34.0%'],[t('Memory'),'62.0%'],[t('Disk'),'2.1 MB/s'],[t('Network'),'8.4 MB/s']].map(([label,value])=>`<div class="card"><h3>${label}</h3><div class="metric">${value}</div>${graph}<span>${label} · NexusDash</span></div>`).join('')+'</div>';else if(route==='settings')$('page').innerHTML=settings();else if(route==='files')$('page').innerHTML=`<h2>${t('FileSearch')}</h2><input placeholder="*.md"><button id="find">${t('FileSearch')}</button><table><thead><tr><th>${t('FileSearch')}</th><th>${t('FileSearchSize')}</th></tr></thead><tbody><tr><td>README.md</td><td>12 KB</td></tr><tr><td>UpdateLog.md</td><td>8 KB</td></tr></tbody></table>`;else $('page').innerHTML=`<h2>${t('HardwareInfo')}</h2><table><tr><td>CPU</td><td>8 cores / 16 threads</td></tr><tr><td>${t('Memory')}</td><td>32 GB</td></tr><tr><td>Windows</td><td>x64</td></tr></table>`;text();document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;render()});if($('mode')){$('mode').value=mode;$('palette').value=palette;$('language').value=culture;$('mode').onchange=e=>{mode=e.target.value;theme()};$('palette').onchange=e=>{palette=e.target.value;theme()};$('language').onchange=e=>{culture=e.target.value;render()}}if($('action')){$('action').onclick=advance;$('cancel').onclick=()=>{clearTimeout(timer);state='canceled';update()};update()}}
function update(){const busy=['checking','downloading'].includes(state);$('action').disabled=busy;$('cancel').hidden=!busy;$('progress').hidden=state!=='downloading';$('action').textContent=t(state==='available'?'UpdateDownload':state==='downloaded'?'UpdateInstall':'UpdateCheck');$('update-status').textContent=state==='available'?t('AboutAvailable').replace('{0}','0.2.0'):state==='failed'?t('AboutFailed').replace('{0}','offline'):t({checking:'AboutChecking',current:'AboutCurrent',downloading:'AboutDownloading',downloaded:'AboutDownloaded',canceled:'AboutCanceled'}[state]||'AboutUpdateDescription')}
function advance(){if(state==='available'){state='downloading';update();timer=setTimeout(()=>{state='downloaded';update()},250)}else if(state==='downloaded'){state='idle';update()}else{state='checking';update();timer=setTimeout(()=>{state=window.updateScenario||'current';update()},250)}}
document.querySelectorAll('[data-route]').forEach(el=>el.onclick=()=>{route=el.dataset.route;render()});$('pause').onclick=()=>{$('log').textContent=t('Pause')};media.addEventListener('change',theme);theme();render();
